DECLARE @LoadDate NVARCHAR(10) = CONVERT(NVARCHAR(10), GETDATE(), 120); --

DECLARE @SourceConnectionName NVARCHAR(MAX) = 'contoso';
DECLARE @TableName NVARCHAR(MAX) = '${TableName}';
DECLARE @PrimaryKey NVARCHAR(MAX) = '${PrimaryKey}';
DECLARE @Location NVARCHAR(MAX) = '/'+ @SourceConnectionName +'c/'+ @TableName +'/loaddate=' + @LoadDate + '/';
DECLARE @WatermarkTS DATETIME = NULL;
DECLARE @columnList NVARCHAR(MAX) = '${ColumnList}';
DECLARE @columnTypeList NVARCHAR(MAX) = '${ColumnList}';

DECLARE @hashcompare NVARCHAR(MAX);
DECLARE @Query NVARCHAR(MAX);

-- Hashcompare is used to only ingest records with changes
-- When the tables is first loaded the view contains no data and no compare is needed
SET @hashcompare = 
CASE WHEN @WatermarkTS IS NULL 
  THEN '' 
  ELSE N' 
LEFT JOIN Bronze.vw_'+ @SourceConnectionName + '_' +  @TableName + ' AS bronze
  ON hashed.['+@PrimaryKey+'] = bronze.['+@PrimaryKey+']
WHERE
     bronze.['+@PrimaryKey+'] IS NULL      -- new record
  OR hashed.row_hash <> bronze.row_hash          -- changed record' END;

-- Query from staging and apply datatypes
SET @Query = N' 
CREATE EXTERNAL TABLE bronze.'+ @SourceConnectionName +'_'+ @TableName +'_' + REPLACE(@LoadDate, '-', '_') + '
WITH (
    LOCATION = ''' + @Location + ''',
    DATA_SOURCE = Bronze,
    FILE_FORMAT = ParquetFormat
)
AS
SELECT hashed.* FROM (
SELECT '
+ @ColumnTypeList +
', HASHBYTES(''SHA2_256'',
        CONCAT_WS(''|'','+ @columnList +')
    ) AS row_hash
, getdate() AS bronze_watermark
FROM OPENROWSET(
    BULK ''' + @Location + '*.parquet'',
    DATA_SOURCE = ''landingzone'',
    FORMAT = ''PARQUET''
) AS lz) AS hashed' + @hashcompare;

EXEC sp_executesql  @Query;
